// Parse Monday board items — extract tracking, phone, postal code
const data = $input.first().json.data || {};
const items = data.boards?.[0]?.items_page?.items || [];

const orders = [];

for (const item of items) {
  const cols = {};
  (item.column_values || []).forEach(c => { cols[c.id] = (c.text || '').trim(); });

  const trackingNumber = cols['text__1'];
  if (!trackingNumber) continue;

  const rawPhone = cols['phone__1'];
  if (!rawPhone) continue;
  const phone = rawPhone.replace(/[^0-9]/g, '');
  if (phone.length < 9) continue;

  // Extract 7-digit Israeli postal code from any column
  let postalCode = '';
  for (const text of Object.values(cols)) {
    const m = text.match(/\b\d{7}\b/);
    if (m) { postalCode = m[0]; break; }
  }

  orders.push({
    item_id: item.id,
    customer_name: item.name,
    tracking_number: trackingNumber,
    phone,
    postal_code: postalCode
  });
}

return orders.map(o => ({ json: o }));

// Check if status changed; update static data
const staticData = $getWorkflowStaticData('global');
const order = $('Parse Orders').item.json;
const tracking = order.tracking_number;

const tmResponse = $input.first().json;
const trackInfo = tmResponse.data?.[0]?.track_info || {};
const currentStatus = trackInfo.latest_status?.status || '';

// Only act on meaningful statuses
const KEY_STATUSES = ['InTransit', 'OutForDelivery', 'Delivered', 'Exception', 'AvailableForPickup', 'Undelivered'];
if (!currentStatus || !KEY_STATUSES.includes(currentStatus)) return [];

const lastKnown = staticData[tracking] || null;
if (currentStatus === lastKnown) return []; // No change

// Save new status
staticData[tracking] = currentStatus;

const lastEvent = trackInfo.latest_event || {};
const eta = trackInfo.time_metrics?.estimated_delivery_date || {};

return [{ json: {
  phone: order.phone,
  customer_name: order.customer_name,
  tracking_number: tracking,
  status: currentStatus,
  sub_status: trackInfo.latest_status?.sub_status || '',
  last_message: lastEvent.description || '',
  last_location: lastEvent.location || '',
  eta_from: eta.from || '',
  eta_to: eta.to || ''
}}];

const { status, last_message, last_location, eta_from, eta_to, phone, tracking_number, customer_name } = $input.first().json;

const warNotice = 'בעקבות מבצע שאגת הארי צפויים עיכובים קלים במשלוחים, אנחנו עם יד על הדופק ובודקים מה עם המשלוח שלך בכל יום ויום.\nנא להיות סבלניים 🙏';

const statusMap = {
  InTransit: { headline: 'בדרכה לארץ! ✈️', detail: 'זמני האספקה הם 7-21 ימי עסקים, אנו נעדכן אותכם בכל שלב ושלב.' },
  OutForDelivery: { headline: 'יוצאת למסירה עכשיו! 🚚', detail: 'השליח בדרכו אליך היום — שמור על הטלפון פתוח!' },
  Delivered: { headline: 'נמסרה! 🎉', detail: 'ההזמנה שלך נמסרה בהצלחה!\nנשמח לשמוע שהגיעה — תהנה מהמוצר! ⚽' },
  Exception: { headline: 'בעיה במשלוח ⚠️', detail: 'אנחנו בודקים מה קורה ונחזור אליך בהקדם.' },
  AvailableForPickup: { headline: 'מחכה לך בנקודת חלוקה 📍', detail: 'החבילה שלך מחכה לאיסוף בנקודת החלוקה הקרובה אליך.' },
  Undelivered: { headline: 'ניסיון מסירה נכשל ⚠️', detail: 'לא הצלחנו למסור את החבילה. ננסה שוב בהקדם.' }
};

const info = statusMap[status];
if (!info) return [];

let etaLine = '';
if (eta_from) {
  try {
    const d = new Date(eta_from);
    const formatted = d.toLocaleDateString('he-IL', { weekday: 'long', day: 'numeric', month: 'long' });
    etaLine = `\nצפי הגעה: ${formatted}`;
  } catch(e) {
    etaLine = `\nצפי הגעה: ${eta_from}`;
  }
}

const firstName = (customer_name || '').split(' ')[0];
const greeting = firstName ? `שלום ${firstName}! 👋\n\n` : '';
const war = (status !== 'Delivered') ? `\n\n${warNotice}` : '';
const trackingLink = `\n\n🔍 *למעקב עצמאי בכל רגע:* https://www.hfd.co.il/איתור-חבילה/\n_(יש להקליד את מספר המעקב ידנית)_`;

const message = `*עדכון משלוח | OneZone* 🏆\n\n${greeting}*סטטוס:* ${info.headline}\n\n${info.detail}${etaLine}${war}\n\n*מס׳ מעקב:* ${tracking_number}${trackingLink}\n\n_להפסקת עדכונים שלח STOP_`;

return [{ json: { phone, message } }];
